class Zeichner extends Turtle {

   // Attribute
   double speed = 10; 

   Zeichner(int x, int y) {
      super(x, y, true);
      setBorderColor(Color.aqua);
      setBorderWidth(5);
      penDown();
   }

   void quadrat(double seitenlänge) {
      for (int i = 0; i < 4; i++) {
         forward(seitenlänge);
         turn(90); // dreht gegen den Uhrzeigersinn
      }
   }

   // TODO1 Erstelle eine Methode quadratRose, die eine beliebige Anzahl von 
   // Quadraten überlappend versetzt in einem Kreis baut. Nutze die quadrat Methode. 

   void quadratRose(int anzahlQuadrate, double seitenlänge) {
      for (int i = 0; i < anzahlQuadrate; i++) {
         quadrat(seitenlänge);
         turn(-(360 / anzahlQuadrate)); 
         setBorderColor(Color.randomColor());
      }
   }

   // TODO1 Bonus für Tüftlerinnen und Tüftler. Methode ergänzen, sodass mehrere "Schichten" gezeichnet werden.
   // Jede Schicht muss um 1.0/anzahlSchichten kleiner werden als die vorherige. 
   void mehrfacheQuadratRose(int anzahlJeSchicht, int anzahlSchichten, double seitenlängeStart) {
      double seitenlänge = seitenlängeStart; 
      for (int i = 0; i < anzahlSchichten; i++) {
         quadratRose(anzahlJeSchicht, seitenlänge);
         seitenlänge = seitenlänge - (seitenlänge * (1.0 / anzahlSchichten)); 
      }
   }

}


new World(800, 600); 
Zeichner z = new Zeichner(400, 300); 

